insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MX', 'default', 'Catálogo de cuentas sobre el código agrupador del SAT (selección para pymes)', '{"en":"Chart of accounts on the SAT grouping code (selection for SMEs)"}'::jsonb, true, 'companies', array['MX-SAT-ER', 'MX-SAT-ESF']::text[], null, 'Anexo 24 de la Resolución Miscelánea Fiscal para 2026, apartado A, inciso a) — código agrupador de cuentas del SAT: los contribuyentes asocian las cuentas de su propio catálogo al código agrupador «por naturaleza y preponderancia de la cuenta», al nivel de cuenta de mayor y subcuenta de primer nivel; Código Fiscal de la Federación, art. 28, fracciones III y IV, y RMF 2026, reglas 2.8.1.5 y 2.8.1.6 — contabilidad en sistemas electrónicos y envío del catálogo, asociado a la subcuenta de primer nivel del agrupador, y de la balanza de comprobación mensual. México no impone un catálogo de cuentas: este paquete usa como catálogo propio una selección de 280 códigos del agrupador (197 subcuentas de primer nivel en que se registra, bajo 83 rubros y cuentas de mayor), con sus códigos y nombres oficiales, de modo que la asociación con el agrupador es la identidad. Una empresa puede abrir subcuentas de segundo nivel debajo de ellas; el agrupador no las numera', 'anexo-24-rmf-2026')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

