insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory)
values
  ('MX', 'MX-P-0', 'Compras a la tasa del 0 %', '{"en":"Purchases at the 0 % rate"}'::jsonb, 'Actos o actividades pagados a la tasa del 0 %', 'percent', 0, 'purchase', 'domestic', date '2010-01-01', null, 'Ley del IVA, art. 2o.-A — tasa del 0 %. Declaración: «Total de los demás actos o actividades pagados a la tasa del 0% de IVA»', 'Z', null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-P-16', 'Compras y gastos al 16 %', '{"en":"Purchases and expenses at 16 %"}'::jsonb, 'IVA trasladado al contribuyente a la tasa general, acreditable al pagarse', 'percent', 16, 'purchase', 'domestic', date '2010-01-01', null, 'Ley del IVA, art. 1o., segundo párrafo — tasa del 16 %; art. 4o. — acreditamiento; art. 5o., fracciones I y II — erogación estrictamente indispensable y deducible para el ISR, impuesto trasladado en forma expresa y por separado en el CFDI. Acreditamiento en el pago: Ley del IVA, art. 5o., fracción III — el IVA trasladado sólo es acreditable cuando ha sido efectivamente pagado; recibido, espera en la subcuenta 119.01 «IVA pendiente de pago» y, pagado, pasa a la 118.01 «IVA acreditable pagado» (Anexo 24 de la RMF 2026). Declaración: «Total de los actos o actividades pagados a la tasa del 16% de IVA» e «IVA de actos o actividades pagados a la tasa del 16%». Un gasto parcialmente deducible para el ISR sólo acredita en esa proporción (art. 5o., fracción I): el código lo acredita todo', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, true, '119.01', 'liva', null, null, null),
  ('MX', 'MX-P-16-RET23', 'Honorarios, arrendamiento o comisiones de personas físicas al 16 %, con retención de dos terceras partes', '{"en":"Fees, rent or commissions from individuals at 16 %, with two thirds withheld"}'::jsonb, 'La persona moral retiene dos terceras partes del IVA que le traslada una persona física', 'percent', 16, 'purchase', 'domestic', date '2010-01-01', null, 'Ley del IVA, art. 1o.-A, fracción II, incisos a) y d) — la persona moral que recibe servicios personales independientes o comisiones, o usa o goza temporalmente bienes, de personas físicas, retiene el impuesto; Reglamento de la Ley del IVA, art. 3o., fracción I — la retención es de las dos terceras partes del impuesto trasladado. El 16 % se acredita en la subcuenta 118.01 y las dos terceras partes retenidas esperan su entero en la 216.10 «Impuestos retenidos de IVA», que se paga en la declaración «IVA retenciones» y no en la de «IVA personas morales» (art. 1o.-A, penúltimo párrafo); el IVA retenido es acreditable una vez enterado (art. 5o., fracción IV). La retención se efectúa en el pago; este código la registra en la factura, y el ISR retenido sobre los mismos pagos (Ley del ISR, arts. 106 y 116, 10 %) no cabe en la misma línea. El factor es -66,667 %, la precisión que admite el formato: dos terceras partes exactas no se pueden escribir, y la retención se desvía un centavo a partir de 1 500 pesos de impuesto: véase el README', 'S', null, 130, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-P-16-RET4', 'Autotransporte terrestre de bienes al 16 %, con retención del 4 %', '{"en":"Road freight at 16 %, with 4 % withheld"}'::jsonb, 'La persona moral retiene el 4 % del valor del flete', 'percent', 16, 'purchase', 'domestic', date '2010-01-01', null, 'Ley del IVA, art. 1o.-A, fracción II, inciso c) — la persona moral que recibe servicios de autotransporte terrestre de bienes retiene el impuesto; Reglamento de la Ley del IVA, art. 3o., fracción II — la retención es del 4 % del valor de la contraprestación, la cuarta parte del 16 %. El 16 % se acredita en la 118.01 y el 4 % retenido espera su entero en la 216.10, que se paga en la declaración «IVA retenciones»', 'S', null, 140, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'rliva', null, null, null),
  ('MX', 'MX-P-8-RF', 'Compras en la región fronteriza, 8 %', '{"en":"Purchases in the border region, 8 %"}'::jsonb, 'IVA trasladado con el estímulo de la región fronteriza, acreditable al pagarse', 'percent', 8, 'purchase', 'domestic', date '2019-01-01', date '2026-12-31', 'Decreto de estímulos fiscales región fronteriza norte (DOF 31-12-2018), artículo Décimo Primero, y Decreto de estímulos fiscales región fronteriza sur (DOF 30-12-2020), artículo Décimo — el proveedor aplica la tasa disminuida en el 50 %; vigencia hasta el 31 de diciembre de 2026 (decreto publicado en el DOF el 31 de diciembre de 2025). Acreditamiento en el pago: Ley del IVA, art. 5o., fracción III — el IVA trasladado sólo es acreditable cuando ha sido efectivamente pagado; recibido, espera en la subcuenta 119.01 «IVA pendiente de pago» y, pagado, pasa a la 118.01 «IVA acreditable pagado» (Anexo 24 de la RMF 2026). Declaración: «Total de los actos o actividades pagados sujetos al estímulo de la región fronteriza» e «IVA pagado sujeto al estímulo de la región fronteriza»', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, true, '119.01', 'decreto-rfn', null, null, null),
  ('MX', 'MX-P-EXE', 'Compras exentas', '{"en":"Exempt purchases"}'::jsonb, 'Actos o actividades pagados por los que no se paga el IVA', 'percent', 0, 'purchase', 'exempt', date '2010-01-01', null, 'Ley del IVA, arts. 9o., 15 y 20 — actos exentos; sin impuesto trasladado. Declaración: «Total de los actos o actividades pagados por los que no se pagará el IVA (exentos)»', 'E', null, 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-P-IMP-16', 'Importación de bienes al 16 %', '{"en":"Imports of goods at 16 %"}'::jsonb, 'IVA pagado en la aduana con el pedimento', 'percent', 16, 'purchase', 'import', date '2010-01-01', null, 'Ley del IVA, art. 24, fracción I — introducción de bienes al país; art. 27 — la base es el valor que se utilice para los fines del impuesto general de importación, adicionado con ese impuesto y los demás que se paguen con motivo de la importación; art. 28 — el impuesto se paga con el de importación, en la aduana, y el pago tiene carácter provisional; art. 5o., fracción III — acreditable al pagarse. Espera en la subcuenta 118.02 «IVA acreditable de importación pagado». Declaración: «Total de los actos o actividades pagados en la importación de bienes y servicios a la tasa del 16% de IVA» y el IVA correspondiente', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-S-0', 'Ventas a la tasa del 0 %', '{"en":"Sales at the 0 % rate"}'::jsonb, 'Actos o actividades del art. 2o.-A de la Ley del IVA', 'percent', 0, 'sale', 'domestic', date '2010-01-01', null, 'Ley del IVA, art. 2o.-A — tasa del 0 % (animales y vegetales no industrializados, alimentos, medicinas de patente y los demás actos que enumera). Declaración: «Valor de los actos o actividades gravados a la tasa del 0% otros». El valor se declara al cobro (arts. 11 y 17); una tasa sin impuesto no puede ser de flujo de efectivo en este formato, y el código lo declara en la fecha de la factura: véase el README', 'Z', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-S-16', 'Ventas y servicios al 16 %', '{"en":"Sales and services at 16 %"}'::jsonb, 'Enajenación de bienes, prestación de servicios y uso o goce temporal de bienes a la tasa general', 'percent', 16, 'sale', 'domestic', date '2010-01-01', null, 'Ley del IVA, art. 1o., segundo párrafo — tasa del 16 %, en la redacción publicada en el DOF el 7 de diciembre de 2009 (la tasa general era del 15 % hasta el 31 de diciembre de 2009). Causación en el cobro: Ley del IVA, arts. 1o.-B, 11 y 17 — el impuesto se causa cuando se cobran efectivamente las contraprestaciones; facturado, espera en la subcuenta 209.01 «IVA trasladado no cobrado» y, cobrado, pasa a la 208.01 «IVA trasladado cobrado», las dos subcuentas que el código agrupador del SAT prevé para ello (Anexo 24 de la RMF 2026). Declaración «IVA personas morales»: «Valor de los actos o actividades gravados a la tasa del 16%» e «IVA a cargo a la tasa del 16%»; un comprobante de egreso (nota de crédito) disminuye los mismos campos (art. 7o.)', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, true, '209.01', 'liva', null, null, null),
  ('MX', 'MX-S-16-RET4', 'Autotransporte terrestre de bienes al 16 %, con retención del 4 %', '{"en":"Road freight at 16 %, with 4 % withheld by the customer"}'::jsonb, 'Flete facturado a una persona moral, que retiene el 4 % del valor de la contraprestación', 'percent', 16, 'sale', 'domestic', date '2010-01-01', null, 'Ley del IVA, art. 1o.-A, fracción II, inciso c) — la persona moral que recibe servicios de autotransporte terrestre de bienes retiene el impuesto; Reglamento de la Ley del IVA, art. 3o., fracción II — la retención es del 4 % del valor de la contraprestación, es decir la cuarta parte del 16 %. El transportista traslada el 16 % (C16) y disminuye de su pago mensual el impuesto que le retuvieron (Ley del IVA, art. 5o.-D, tercer párrafo; declaración: campo «IVA retenido»). La retención se efectúa en el pago (art. 1o.-A, penúltimo párrafo); este código la registra en la factura, porque un código de flujo de efectivo sólo lleva una partida de impuesto: véase el README', 'S', null, 30, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-S-8-RF', 'Ventas y servicios en la región fronteriza, 8 %', '{"en":"Sales and services in the border region, 8 %"}'::jsonb, 'Tasa del 16 % con el crédito del 50 % de los decretos de la región fronteriza norte y sur', 'percent', 8, 'sale', 'domestic', date '2019-01-01', date '2026-12-31', 'Decreto de estímulos fiscales región fronteriza norte (DOF 31-12-2018), artículo Décimo Primero, y Decreto de estímulos fiscales región fronteriza sur (DOF 30-12-2020), artículo Décimo — crédito fiscal equivalente al 50 % de la tasa del art. 1o. de la Ley del IVA, aplicado «en forma directa sobre la tasa», para quien enajena bienes, presta servicios independientes u otorga el uso o goce temporal de bienes en locales o establecimientos ubicados en la región, con entrega material de los bienes o prestación de los servicios en ella, inscrito en el padrón de beneficiarios mediante el aviso que exige cada decreto. En vigor desde el 1 de enero de 2019 en la región norte y desde el 1 de enero de 2021 en la región sur; vigencia de los dos decretos prorrogada hasta el 31 de diciembre de 2026 por el decreto publicado en el DOF el 31 de diciembre de 2025, de ahí valid_to. Las regiones son listas de municipios (artículo Primero de cada decreto) que la tabla territories no tiene: el paquete no puede condicionar el código a la región, véase el README. Causación en el cobro: Ley del IVA, arts. 1o.-B, 11 y 17 — el impuesto se causa cuando se cobran efectivamente las contraprestaciones; facturado, espera en la subcuenta 209.01 «IVA trasladado no cobrado» y, cobrado, pasa a la 208.01 «IVA trasladado cobrado», las dos subcuentas que el código agrupador del SAT prevé para ello (Anexo 24 de la RMF 2026). Declaración: «Valor de los actos o actividades gravados sujetos al estímulo de la región fronteriza» e «IVA a cargo sujeto al estímulo de la región fronteriza»', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, true, '209.01', 'decreto-rfn', null, null, null),
  ('MX', 'MX-S-EXE', 'Actos exentos', '{"en":"Exempt acts"}'::jsonb, 'Enajenaciones, servicios o uso o goce temporal exentos', 'percent', 0, 'sale', 'exempt', date '2010-01-01', null, 'Ley del IVA, art. 9o. (enajenación: suelo, casa habitación, libros, periódicos y revistas, bienes muebles usados salvo los enajenados por empresas, entre otros), art. 15 (servicios: comisiones de créditos hipotecarios para vivienda, enseñanza con autorización, transporte público terrestre de personas, entre otros) y art. 20 (uso o goce temporal de casa habitación, entre otros) — no se paga el impuesto. Declaración: «Valor de los actos o actividades por los que no se deba pagar el impuesto (exentos)»', 'E', null, 60, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-S-EXP', 'Exportación, tasa del 0 %', '{"en":"Exports, 0 % rate"}'::jsonb, 'Exportación de bienes o servicios', 'percent', 0, 'sale', 'export', date '2010-01-01', null, 'Ley del IVA, art. 29 — las empresas residentes en el país calculan el impuesto aplicando la tasa del 0 % al valor de la enajenación de bienes o prestación de servicios cuando se exporten; fracción I — la exportación definitiva en los términos de la Ley Aduanera, y las demás fracciones. Declaración: «Valor de los actos o actividades gravados a la tasa del 0% exportación»', 'G', null, 50, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('MX', 'MX-S-NOBJ', 'Actos no objeto del impuesto', '{"en":"Acts outside the scope of the tax"}'::jsonb, 'Actos que no son objeto del IVA', 'percent', 0, 'sale', 'not_subject', date '2010-01-01', null, 'Ley del IVA, art. 4o.-A — actos o actividades no objeto del impuesto: los que el contribuyente no realiza en territorio nacional conforme a los arts. 10, 16 y 21, y los distintos de los del art. 1o. realizados en territorio nacional, cuando por ellos obtiene ingresos y soportó IVA en los gastos e inversiones para obtenerlos. Declaración: «Valor de los actos o actividades no objeto del impuesto»', 'O', null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'liva', null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory;

