insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MX', 'MX-IVA-PM', 'Declaración del pago definitivo mensual — IVA personas morales', array['month']::declaration_period[], 'month'::declaration_period, date '2024-01-01', null, 'Ley del IVA, art. 5o.-D — el impuesto se calcula por cada mes de calendario y se paga mediante declaración; el trimestre del art. 5o.-F sólo existe para ciertas personas físicas arrendadoras, fuera del alcance de una declaración de personas morales. Los campos son los de la plataforma «Presenta tu declaración de pagos definitivos de IVA del ejercicio 2024 en adelante», descritos en la guía de llenado del SAT de marzo de 2024, de ahí valid_from; la declaración se presenta en el portal del SAT, prellenada con los CFDI, y no tiene números de renglón: los identificadores de este paquete son siglas propias', true,'depends_on_taxpayer'::filing_deadline_rule, null, null, 'Ley del IVA, art. 5o.-D, segundo párrafo — a más tardar el día 17 del mes siguiente; Decreto que compila diversos beneficios fiscales (DOF 26-12-2013), art. 5.1 — quien deba presentar una declaración provisional o definitiva de impuestos federales el día 17 puede hacerlo, según el sexto dígito numérico de su RFC, el día 17 más uno (1 y 2), dos (3 y 4), tres (5 y 6), cuatro (7 y 8) o cinco (9 y 0) días hábiles, salvo los contribuyentes que el mismo artículo excluye (quienes dictaminan sus estados financieros, los grandes contribuyentes del art. 20, apartado B, del Reglamento Interior del SAT, la Federación y las entidades federativas, entre otros); Código Fiscal de la Federación, art. 12 — días hábiles. El día depende del RFC de cada contribuyente', 'decreto-compila-2013', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('MX', 'MX-IVA-PM', 'G16', 'base', 'Valor de los actos o actividades gravados a la tasa del 16%', '{"en":"Value of acts or activities taxed at 16%"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Guía de llenado de la declaración del pago definitivo «IVA personas morales» (SAT, marzo de 2024), sección «IVA a cargo»; prellenado por el SAT con los CFDI de ingreso con método de pago «Pago en una sola exhibición» y los complementos de pago del periodo', 'guia-iva-pm'),
  ('MX', 'MX-IVA-PM', 'GRF', 'base', 'Valor de los actos o actividades gravados sujetos al estímulo de la región fronteriza', '{"en":"Value of taxed acts or activities under the border region incentive"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Guía de llenado de la declaración del pago definitivo «IVA personas morales» (SAT, marzo de 2024), sección «IVA a cargo»; el detalle separa la región fronteriza norte (RFN) y sur (RFS)', 'guia-iva-pm'),
  ('MX', 'MX-IVA-PM', 'G0E', 'base', 'Valor de los actos o actividades gravados a la tasa del 0% exportación', '{"en":"Value of acts or activities taxed at 0% — exports"}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Guía de llenado de la declaración del pago definitivo «IVA personas morales» (SAT, marzo de 2024), sección «IVA a cargo» — capturado por el contribuyente según sus papeles de trabajo', 'guia-iva-pm'),
  ('MX', 'MX-IVA-PM', 'G0O', 'base', 'Valor de los actos o actividades gravados a la tasa del 0% otros', '{"en":"Value of acts or activities taxed at 0% — other"}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Guía de llenado de la declaración del pago definitivo «IVA personas morales» (SAT, marzo de 2024), sección «IVA a cargo»; prellenado por el SAT con los CFDI de ingreso con método de pago «Pago en una sola exhibición» y los complementos de pago del periodo', 'guia-iva-pm'),
  ('MX', 'MX-IVA-PM', 'GSUM', 'total', 'Suma de los actos o actividades gravados', '{"en":"Total taxed acts or activities"}'::jsonb, 50, null, array['G16', 'GRF', 'G0E', 'G0O']::text[], '{}'::text[], null, null, false, false, null, 'Guía de llenado de la declaración del pago definitivo «IVA personas morales» (SAT, marzo de 2024), «es el resultado de sumar» los cuatro campos anteriores', 'guia-iva-pm'),
  ('MX', 'MX-IVA-PM', 'EXE', 'base', 'Valor de los actos o actividades por los que no se deba pagar el impuesto (exentos)', '{"en":"Value of acts or activities on which no tax is payable (exempt)"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Guía de llenado de la declaración del pago definitivo «IVA personas morales» (SAT, marzo de 2024), sección «IVA a cargo»; prellenado por el SAT con los CFDI de ingreso con método de pago «Pago en una sola exhibición» y los complementos de pago del periodo', 'guia-iva-pm'),
  ('MX', 'MX-IVA-PM', 'NOB', 'base', 'Valor de los actos o actividades no objeto del impuesto', '{"en":"Value of acts or activities outside the scope of the tax"}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Guía de llenado de la declaración del pago definitivo «IVA personas morales» (SAT, marzo de 2024), sección «IVA a cargo»; prellenado por el SAT con los CFDI de ingreso con método de pago «Pago en una sola exhibición» y los complementos de pago del periodo', 'guia-iva-pm'),
