insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('MX-SAT-ER', 'MX', 'default', 'Estado de resultados', 'income_statement', 'MX-NIF', date '1970-01-01', null, 'Ley General de Sociedades Mercantiles, art. 172, inciso D) — «un estado que muestre, debidamente explicados y clasificados, los resultados de la sociedad durante el ejercicio». Estructura mínima: los rubros de ingresos, costos, gastos y resultado integral de financiamiento del código agrupador del SAT (Anexo 24 de la RMF 2026, apartado A, inciso a)), con los subtotales de utilidad bruta, de operación, antes de impuestos y neta. La NIF B-3 «Estado de resultado integral» del CINIF fija la presentación normativa; su texto está protegido por derechos del CINIF y no se transcribe', 'lgsm'),
  ('MX-SAT-ESF', 'MX', 'default', 'Estado de situación financiera', 'balance_sheet', 'MX-NIF', date '1970-01-01', null, 'Ley General de Sociedades Mercantiles, art. 172, inciso C) — «un estado que muestre la situación financiera de la sociedad a la fecha de cierre del ejercicio». Estructura mínima: los rubros de activo, pasivo y capital contable y sus cuentas de mayor, tal como los agrupa el código agrupador del SAT (Anexo 24 de la RMF 2026, apartado A, inciso a)). La NIF B-6 «Estado de situación financiera» del CINIF fija la presentación normativa; su texto está protegido por derechos del CINIF y no se transcribe', 'lgsm')
