update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Código Fiscal de la Federación, art. 29, fracción IV, incisos b) y c), y art. 29-A, fracción II — el folio que identifica fiscalmente al comprobante (folio fiscal, UUID) lo asigna el Servicio de Administración Tributaria, a través de un proveedor de certificación autorizado (art. 29 Bis), al timbrar el CFDI; no lo asigna el emisor. La serie y el folio internos del emisor son campos opcionales del Anexo 20 y ninguna norma exige que sean consecutivos: el número que declara este paquete es el de la pieza contable, correlativo por diario y por año, y no el del CFDI',
  numbering_source_key          = 'cff',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'payment_date',
  tax_point_legal_reference     = 'Ley del IVA, art. 11, primer párrafo — la enajenación se efectúa «en el momento en el que efectivamente se cobren las contraprestaciones y sobre el monto de cada una de ellas»; art. 17, primer párrafo — lo mismo para la prestación de servicios, salvo los intereses del art. 18-A, que causan el impuesto conforme se devengan; art. 22 — lo mismo para el uso o goce temporal de bienes; art. 1o.-B — qué se considera efectivamente cobrado; art. 5o., fracción III — el IVA trasladado sólo es acreditable cuando ha sido efectivamente pagado. Las tasas del 16 % y del 8 % de este paquete son de flujo de efectivo (cash_basis) y llevan el impuesto a su cuenta y a su campo de la declaración en el cobro o en el pago; la fecha de la factura no fija la causación',
  tax_point_source_key          = 'liva',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Código de Comercio, art. 33 — sistema de contabilidad que permita identificar las operaciones individuales y conectarlas con los documentos comprobatorios originales; Código Fiscal de la Federación, art. 29-A, cuarto párrafo — un CFDI sólo se cancela con la aceptación de la persona a cuyo favor se expidió, a más tardar en el mes de la declaración anual del ejercicio, y la RMF 2026, regla 2.7.1.35, enumera los casos sin aceptación. Una factura contabilizada se anula con un comprobante de egreso (nota de crédito) que la nombra, nunca volviendo a borrador',
  posted_edit_policy_source_key = 'cff',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Código Fiscal de la Federación, art. 29 — toda factura se emite como Comprobante Fiscal Digital por Internet (CFDI) y sólo es válida después de su certificación (timbrado): antes de expedirla, el emisor la remite al SAT o a un proveedor de certificación autorizado (PAC, art. 29 Bis y RMF 2026, regla 2.7.2.1), que valida los requisitos del art. 29-A, le asigna el folio fiscal e incorpora el sello digital del SAT. Es un régimen de validación previa (clearance) obligatorio para todo contribuyente que expide comprobantes, no un intercambio entre empresas. El formato es el Anexo 20 de la RMF, versión 4.0, en vigor desde el 1 de enero de 2022 y, según la página del SAT «Formato de factura (Anexo 20)», única válida desde el 1 de abril de 2023. EKWO NO GENERA, NO TIMBRA Y NO TRANSMITE CFDI: ningún componente de packages/formats escribe el XML del Anexo 20 ni habla con un PAC, y un documento emitido desde Ekwo no es un comprobante fiscal. El CFDI se timbra con un PAC o con el servicio gratuito del SAT, y Ekwo registra la operación en la contabilidad. Por eso profile, mandatory_from y obligation quedan vacíos aunque la obligación exista: profile nombra un perfil construido sobre EN 16931 que una pieza de packages/formats escribe, el CFDI no es ni lo uno ni lo otro, y el formato no admite una obligación con fecha sin perfil ni tiene palabra para «válida sólo tras la certificación de un tercero» (véase docs/international.md). El RFC identifica al emisor y al receptor y no tiene código ISO 6523: party_scheme y vat_scheme quedan vacíos',
  einvoice_source_key           = 'cff',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = array['csv']::text[],
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'MX';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('MX', 'cfdi_not_stamped', 'always', 'Este documento no es un Comprobante Fiscal Digital por Internet (CFDI): no lleva el folio fiscal ni el sello digital del Servicio de Administración Tributaria que asigna un proveedor de certificación autorizado. Sólo el CFDI timbrado ampara la operación para efectos fiscales.', '{"en":"This document is not a Comprobante Fiscal Digital por Internet (CFDI): it carries neither the fiscal folio nor the digital seal of the Tax Administration Service assigned by an authorised certification provider. Only the stamped CFDI supports the transaction for tax purposes."}'::jsonb, 10, date '1970-01-01', null, 'Código Fiscal de la Federación, art. 29, primer párrafo y fracciones IV y V — el comprobante se emite como documento digital y se remite al SAT, o al proveedor de certificación que autoriza (art. 29 Bis), antes de su expedición, para validarlo, asignarle folio e incorporarle el sello digital del SAT; la representación impresa «únicamente presume la existencia de dicho comprobante»; art. 29-A, fracción II. Ekwo no timbra ni transmite CFDI: la frase evita que el documento que Ekwo produce se tome por el comprobante fiscal'),
  ('MX', 'cfdi_ppd', 'cash_basis', 'Pago en parcialidades o diferido (PPD): cada cobro se ampara con un CFDI con complemento para recepción de pagos, y el impuesto al valor agregado trasladado se causa en el momento en que se cobra efectivamente la contraprestación.', '{"en":"Payment in instalments or deferred (PPD): each collection is supported by a CFDI with the payment receipt complement, and the value added tax charged falls due when the consideration is actually collected."}'::jsonb, 20, date '1970-01-01', null, 'Código Fiscal de la Federación, art. 29, primer párrafo, y art. 29-A, fracción VII, inciso b) — la operación que no se paga en una sola exhibición se ampara con un CFDI por el valor total y un CFDI por cada pago; RMF 2026, regla 2.7.1.32 — CFDI con «Complemento para recepción de Pagos»; Ley del IVA, arts. 1o.-B, 11 y 17 — el impuesto se causa en el cobro'),
  ('MX', 'export', 'export', 'Exportación — tasa del 0 % del impuesto al valor agregado (artículo 29 de la Ley del IVA).', '{"en":"Export — value added tax at 0 % (article 29 of the Value Added Tax Act)."}'::jsonb, 30, date '1970-01-01', null, 'Ley del IVA, art. 29 — las empresas residentes en el país calculan el impuesto a la tasa del 0 % cuando los bienes o servicios se exportan; el CFDI lo indica en su campo «Exportación» (Anexo 20, versión 4.0)'),
  ('MX', 'exempt', 'exempt', 'Acto o actividad exento del impuesto al valor agregado (artículos 9, 15 o 20 de la Ley del IVA, según el acto).', '{"en":"Act or activity exempt from value added tax (articles 9, 15 or 20 of the Value Added Tax Act, depending on the act)."}'::jsonb, 40, date '1970-01-01', null, 'Código Fiscal de la Federación, art. 29-A, fracción VII, inciso a) — el comprobante desglosa los impuestos trasladados por tasa, y un acto exento no traslada ninguno; Ley del IVA, arts. 9 (enajenaciones), 15 (servicios) y 20 (uso o goce temporal de bienes) — actos exentos')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
